-- St. Joseph's first groups (BP app docs/plans/rsvp-and-groups, ticket 04's list, all 14 approved by
-- Jesse on 2026-10-17; loaded with his yes on 2026-10-18). Each fact is from the group's own pages or
-- the proof links in BP app docs/plans/rsvp-and-groups/assets/04-real-groups.md; the words are the
-- agent's. Women of Today's meeting night is from a search snippet of mnwt.org (its robots file
-- turns readers away). A group already there by name is left as it is, so this runs once.

insert into public.clubs (name, kind, schedule, location, description, page_url, entry_id, place_entry_id, meets, status)
select v.name, v.kind, v.schedule, v.location, v.description, v.page_url, v.entry_id, v.place_entry_id, v.meets, 'approved'
from (values
  ('American Legion Post 328', 'Veterans', '4th Tuesdays at 7 PM', 'American Legion, 101 W Minnesota St', 'St. Joseph''s American Legion, the John Kuebelbeck Post. Veterans meet at the Post once a month, and the Post hosts 500 cards and bingo.', 'https://johnkuebelbeckpost328.org/', 'group-american-legion-post-328', '328-american-legion-post', '[{"what": "Membership meeting", "days": ["tue"], "weeks": [4], "time": "19:00"}, {"what": "500 cards", "days": ["wed"], "weeks": null, "time": "13:30"}, {"what": "Bingo", "days": ["mon"], "weeks": [2, 4], "time": "18:30"}]'::jsonb),
  ('Book Discussion Group', 'Book club', '1st Tuesdays at 9:30 AM', 'Fireside Room, Resurrection Lutheran', 'One book a month, talked over in the Fireside Room. Open to anyone.', 'https://rlcstjoe.com/specialty-groups/', 'group-rlc-book-discussion', 'resurrection-lutheran-church', '[{"what": "Book discussion", "days": ["tue"], "weeks": [1], "time": "09:30"}]'::jsonb),
  ('Knights of Columbus 7057', 'Faith and service', '2nd Mondays', 'Parish school, Church of St. Joseph', 'About 240 members. Their parish breakfast is open to all: first Sundays, October to May, 8:30 to noon in Heritage Hall.', 'https://kc7057.mnknights.org/', 'group-knights-of-columbus-7057', 'church-jospehs-st', '[{"what": "Meeting", "days": ["mon"], "weeks": [2], "time": null}, {"what": "Parish breakfast", "days": ["sun"], "weeks": [1], "time": "08:30", "months_off": [6, 7, 8, 9], "where": "Heritage Hall"}]'::jsonb),
  ('Laundry Love', 'Volunteering', '1st and 3rd Tuesdays, 5 to 8 PM', 'St. Joseph Laundromat', 'Volunteer nights at the laundromat, run by the Central Minnesota Catholic Worker since 2022.', 'https://centralminnesotacatholicworker.wordpress.com/', 'group-laundry-love', 'st-joseph-laundromat', '[{"what": "Laundry night", "days": ["tue"], "weeks": [1, 3], "time": "17:00"}]'::jsonb),
  ('Legion Auxiliary Unit 328', 'Service club', '1st Tuesdays at 6:30 PM', 'American Legion', 'Meets once a month at the Legion and runs the poppy drive each spring.', 'https://johnkuebelbeckpost328.org/auxiliary', 'group-legion-auxiliary-unit-328', '328-american-legion-post', '[{"what": "Meeting", "days": ["tue"], "weeks": [1], "time": "18:30"}]'::jsonb),
  ('Parish Quilt Group', 'Quilting', 'Mondays at 7 AM, fall to early spring', 'Heritage Hall, Church of St. Joseph', 'About 14 quilters who have met for 39 years. Their quilts go to the parish''s yearly quilt auction.', 'https://www.joetownrocks.org/quilt-auction.html', 'group-parish-quilt-group', 'church-jospehs-st', '[{"what": "Quilting", "days": ["mon"], "weeks": null, "time": "07:00", "months_off": [4, 5, 6, 7, 12]}]'::jsonb),
  ('Sons of the American Legion', 'Service club', '1st Mondays at 7 PM', 'American Legion', 'Squadron 328. Meets once a month at the Legion.', 'https://johnkuebelbeckpost328.org/sons-of-legion', 'group-sons-of-the-american-legion-328', '328-american-legion-post', '[{"what": "Meeting", "days": ["mon"], "weeks": [1], "time": "19:00"}]'::jsonb),
  ('Spinning and Knitting Bee', 'Handwork', '1st Saturdays, November to April, 1 PM', 'Meyer Farm Project', 'Bring your spinning, knitting or other handwork. Free, the first Saturday of the month, November to April.', 'https://meyerfarmproject.com/events/', 'group-meyer-farm-crafting-bee', 'meyer-farm-project', '[{"what": "Crafting Bee", "days": ["sat"], "weeks": [1], "time": "13:00", "months_off": [5, 6, 7, 8, 9, 10]}]'::jsonb),
  ('St. Joe Rod and Gun Club', 'Outdoors', '3rd Mondays at 7 PM', 'American Legion', 'Fishing and the outdoors. Meets once a month at the Legion, with nights like birdhouse building.', 'https://stjoerodandgunclub.org/', 'group-st-joe-rod-and-gun-club', '328-american-legion-post', '[{"what": "Meeting", "days": ["mon"], "weeks": [3], "time": "19:00"}]'::jsonb),
  ('St. Joseph Lions Club', 'Service club', '1st and 3rd Tuesdays at 6 PM', 'Lions Building, Millstream Park', 'Supper at 6, meeting at 6:30, twice a month. The Lions run the town''s Fourth of July parade and the Easter party.', 'https://e-clubhouse.org/sites/stjosephmn/', 'group-st-joseph-lions-club', 'millstream-park', '[{"what": "Meeting", "days": ["tue"], "weeks": [1, 3], "time": "18:00"}]'::jsonb),
  ('St. Joseph Women of Today', 'Service club', '2nd Mondays at 6 PM', 'St. Joseph Fire Station', 'Service projects around town, like a blanket-making day and a kids'' bike safety day.', 'https://mnwt.org/chapters/', 'group-st-joseph-women-of-today', null, '[{"what": "Meeting", "days": ["mon"], "weeks": [2], "time": "18:00"}]'::jsonb),
  ('Stitch and Sip', 'Knitting', '4th Wednesdays at 6 PM, in summer', 'Milk & Honey Ciders', 'A monthly knitting night at Milk & Honey, hosted by Yellow Brick Knits.', 'https://www.milkandhoneyciders.com/events', 'group-stitch-and-sip', 'milk-and-honey-ciders', '[{"what": "Stitch and Sip", "days": ["wed"], "weeks": [4], "time": "18:00", "months_off": [1, 2, 3, 4, 9, 10, 11, 12]}]'::jsonb),
  ('The Yarnovers', 'Knitting and crafts', 'Wednesdays at 9 AM', 'Fellowship Hall, Resurrection Lutheran', 'Knitting, crochet and quilting, every Wednesday morning.', 'https://rlcstjoe.com/specialty-groups/', 'group-rlc-yarnovers', 'resurrection-lutheran-church', '[{"what": "Yarnovers", "days": ["wed"], "weeks": null, "time": "09:00"}]'::jsonb),
  ('Thursday Bible Study', 'Bible study', 'Thursdays at 9 AM', 'Fireside Room, Resurrection Lutheran', 'Weekly Bible study in the Fireside Room, or join on Zoom. Drop-ins welcome.', 'https://rlcstjoe.com/adult-bible-study/', 'group-rlc-thursday-bible-study', 'resurrection-lutheran-church', '[{"what": "Bible study", "days": ["thu"], "weeks": null, "time": "09:00"}]'::jsonb)
) as v (name, kind, schedule, location, description, page_url, entry_id, place_entry_id, meets)
where not exists (select 1 from public.clubs c where c.name = v.name);
